import{_ as a}from"./chunks/hotel.CGP_f0Jj.js";import{_ as i,o as e,c as d,a5 as s}from"./chunks/framework.bIR-4glx.js";const b=JSON.parse('{"title":"写作篇：从初稿到可验证修订","description":"从真实受众与无辅助初稿出发，训练意图、事实、结构、语域、反馈吸收、翻译边界、AI 协作、异步交接和署名责任。","frontmatter":{"title":"写作篇：从初稿到可验证修订","description":"从真实受众与无辅助初稿出发，训练意图、事实、结构、语域、反馈吸收、翻译边界、AI 协作、异步交接和署名责任。","updated":"2026-10-19T00:00:00.000Z","sources_checked":"2026-09-02T00:00:00.000Z"},"headers":[],"relativePath":"threads/part-1/6-writing.md","filePath":"threads/part-1/6-writing.md","lastUpdated":1792368000000}'),l={name:"threads/part-1/6-writing.md"};function r(n,t,h,p,o,c){return e(),d("div",null,[...t[0]||(t[0]=[s('<h1 id="写作篇-从初稿到可验证修订" tabindex="-1">写作篇：从初稿到可验证修订 <a class="header-anchor" href="#写作篇-从初稿到可验证修订" aria-label="Permalink to &quot;写作篇：从初稿到可验证修订&quot;">​</a></h1><p>这份指南最早开始于 2017 年。那时我想分享自己如何学英语，写下一些词汇、听力、阅读和口语经验。后来，朋友半开玩笑地叫我“那个有很多 star 的 Markdown 工程师”。可在恋爱、创业、失败和生活失序之间，写作也曾停下来。</p><p>重新回来以后，我越来越相信：写作不是把脑海里的句子装饰得更漂亮，而是把一个人想让别人理解、核对、决定或继续完成的事情，组织成可以离开作者仍然工作的形状。</p><p>我曾经想删掉整个写作篇，因为觉得自己不够成功，没有资格谈写作。直到一篇创业失败的文章收到许多具体回应，我才意识到，写作不必等凯旋之后才开始。它可以保存一个人当时知道什么、误判什么、承担什么，也可以让失败离开情绪以后继续接受事实和读者的追问。</p><p><img src="'+a+`" alt="度假酒店项目中的真实场景" loading="lazy" decoding="async" width="800" height="522"></p><p>本章不教你生产“像 AI 一样流畅”的段落。它提供一条可追溯的路径：先确定真实受众和任务，保存未经润色的初稿；把事实、结构、句子、语域和交付分开修订；记录每一项修改的理由；让读者复述或采取行动；最后在新主题和新受众中检查能力是否迁移。</p><h2 id="本章速览" tabindex="-1">本章速览 <a class="header-anchor" href="#本章速览" aria-label="Permalink to &quot;本章速览&quot;">​</a></h2><ul><li>写作先定义受众、任务、交付标准和署名责任，再选择文体；</li><li>保存限时无辅助初稿，不让翻译或 AI 覆盖真实起点；</li><li>区分事实、来源、推断、个人经验和等待验证的判断；</li><li>用文档骨架让每一段承担工作，再处理句子与风格；</li><li>翻译可以帮助比较意义，不能替作者决定语气、责任和事实；</li><li>反馈要记录采纳、拒绝和理由，不能只保存改好的终稿；</li><li>AI 可以诊断、模拟读者和生成变式，不应替你虚构、署名或承担结果；</li><li>邮件、状态更新、决策记录和跨时区交接也是完整写作；</li><li>十四天追踪一个真实场景、一份原始初稿和一次平行交付。</li></ul><h2 id="_1-先定义写作任务" tabindex="-1">1. 先定义写作任务 <a class="header-anchor" href="#_1-先定义写作任务" aria-label="Permalink to &quot;1. 先定义写作任务&quot;">​</a></h2><p>同样是“写一篇文章”，需要的结构可能完全不同：</p><table tabindex="0"><thead><tr><th>任务</th><th>练习条件</th><th>完成证据</th></tr></thead><tbody><tr><td>说明</td><td>受众不熟悉背景，300-600 字</td><td>读者能复述主旨、关键依据和下一步</td></tr><tr><td>请求</td><td>有明确关系、资源和截止时间</td><td>对方知道需要做什么、何时做、可以怎样拒绝或确认</td></tr><tr><td>状态更新</td><td>没有会议补充，跨时区阅读</td><td>读者知道完成、风险、阻塞、负责人和下一检查点</td></tr><tr><td>决策</td><td>至少两个选项，有成本与期限</td><td>决策者看见依据、代价、未知项、建议与退出条件</td></tr><tr><td>叙事</td><td>一个具体事件，不替别人编造心理</td><td>时间线清楚，事实、感受、推断和后来解释分开</td></tr><tr><td>反思</td><td>回看经历，区分当时信息与现在信息</td><td>提出一个可以验证的下一步，不把结果写成命运</td></tr><tr><td>交接</td><td>下一位执行者不在现场</td><td>对方能够只凭文档继续、检查并在失败时回滚</td></tr></tbody></table><p>动笔前写四句话：谁要读；读完需要理解或完成什么；哪些证据支持；哪些事实、隐私、权限和责任不能越过。</p><p>使用<a href="./../../templates/writing-evidence">写作证据卡</a>，把任务、初稿、来源、反馈、修改理由、交付和延迟复测放在同一页。</p><h2 id="_2-保存未经修饰的初稿" tabindex="-1">2. 保存未经修饰的初稿 <a class="header-anchor" href="#_2-保存未经修饰的初稿" aria-label="Permalink to &quot;2. 保存未经修饰的初稿&quot;">​</a></h2><p>选择一个真实任务，在 15-25 分钟内完成第一版。可以先写三到五个关键词或一个简单提纲，但不查整句译文，不让 AI 代写，不删除失败段落。</p><p>记录条件：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">真实受众与关系：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">任务、体裁和完成标准：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">字数与时间限制：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">允许的词典、翻译、资料和 AI：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">必须核对的事实：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">隐私、版权、保密和署名边界：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">原始初稿位置：</span></span></code></pre></div><p>初稿的价值不是好看，而是显示你在没有后续支架时怎样选择内容、结构和语言。若第一版直接来自机器翻译或模型生成，以后只能比较两个成品，无法判断作者能力改变了什么。</p><p>初稿完成后先不要修改，写下：我真正想让读者记住的一句话；我最没有把握的事实；我最可能藏在漂亮话里的空缺。</p><h2 id="_3-先建立事实与责任账本" tabindex="-1">3. 先建立事实与责任账本 <a class="header-anchor" href="#_3-先建立事实与责任账本" aria-label="Permalink to &quot;3. 先建立事实与责任账本&quot;">​</a></h2><p>文字一旦交付，就可能改变决定、关系和资源。先把内容按证据类型分开：</p><table tabindex="0"><thead><tr><th>内容</th><th>最低记录</th><th>常见风险</th></tr></thead><tbody><tr><td>可核对事实</td><td>原始来源、版本、日期和上下文</td><td>过期、断章取义或转述失真</td></tr><tr><td>数字与比较</td><td>口径、样本、时间范围和基准</td><td>分母消失、选择性比较或伪精确</td></tr><tr><td>引语</td><td>原文、说话者、位置和许可</td><td>改变语气、错误归属或超出合理使用</td></tr><tr><td>个人经历</td><td>当时知道什么、后来知道什么</td><td>把记忆写成完整记录或把幸运写成规律</td></tr><tr><td>推断与建议</td><td>推理链、假设、风险和反例</td><td>把判断伪装成事实</td></tr><tr><td>他人信息</td><td>最少必要范围与明确许可</td><td>暴露身份、替别人解释内心或无法撤回</td></tr></tbody></table><p>可以建立一张来源账本：主张、来源位置、核验日期、置信度、是否能公开、什么新证据会改变它。没有来源并不等于不能写个人经验，但必须诚实命名它的证据等级。</p><h2 id="_4-用骨架决定每一段的工作" tabindex="-1">4. 用骨架决定每一段的工作 <a class="header-anchor" href="#_4-用骨架决定每一段的工作" aria-label="Permalink to &quot;4. 用骨架决定每一段的工作&quot;">​</a></h2><p>写作卡住时，往往不是词不够，而是作者还没有决定信息之间的关系。先用最简单的骨架：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">读者当前面对的问题：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">我给出的直接回答：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">两到三个依据：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">一个具体例子或最小事实：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">限制、反例或仍然未知：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">读者的下一步：</span></span></code></pre></div><p>然后给每一段标一个功能：背景、问题、主张、理由、证据、例子、转折、限制、请求、决定或交接。若一段承担四件事，拆开；若三段承担同一件事，合并或删除。</p><p>叙事也需要骨架，但不是成功模板。写清发生了什么、当时知道什么、做了什么、造成什么影响、现在怎样解释。不要把 STAR 等结构变成制造胜利的机器；结果不好也可以成为可信故事。</p><h2 id="_5-翻译不是代写-建立意义对照" tabindex="-1">5. 翻译不是代写：建立意义对照 <a class="header-anchor" href="#_5-翻译不是代写-建立意义对照" aria-label="Permalink to &quot;5. 翻译不是代写：建立意义对照&quot;">​</a></h2><p>母语可以帮助找到真实意图和复杂概念，翻译工具可以暴露两种表达的差异。问题出现在作者把译文当成无需判断的终稿。</p><p>使用三栏：</p><table tabindex="0"><thead><tr><th>我真正想表达</th><th>英文首版</th><th>比较后决定</th></tr></thead><tbody><tr><td>事实、关系、语气与下一步</td><td>自己当前能写出的版本</td><td>哪个意义丢失、增强、变弱或被机器补造</td></tr></tbody></table><p>翻译后检查：主体和责任是否改变；确定性是否被放大；否定和条件范围是否变化；礼貌是否变成含糊；中文成语或制度概念是否被替换成错误等价物。</p><p>如果任务就是翻译，还要保存原文版本、用途、受众、术语表、不可直译项、审校者和最终责任人。译得自然不等于译得忠实，也不等于适合当前语域。</p><h2 id="_6-五次修订-各自只问一类问题" tabindex="-1">6. 五次修订，各自只问一类问题 <a class="header-anchor" href="#_6-五次修订-各自只问一类问题" aria-label="Permalink to &quot;6. 五次修订，各自只问一类问题&quot;">​</a></h2><p>不要在同一遍里同时修事实、结构、语法和标点。按风险顺序修：</p><h3 id="第一遍-任务与事实" tabindex="-1">第一遍：任务与事实 <a class="header-anchor" href="#第一遍-任务与事实" aria-label="Permalink to &quot;第一遍：任务与事实&quot;">​</a></h3><p>文章是否回答问题？数字、时间、人物、引语和来源能否核对？有没有读者必须知道却被省略的条件？</p><h3 id="第二遍-结构与证据" tabindex="-1">第二遍：结构与证据 <a class="header-anchor" href="#第二遍-结构与证据" aria-label="Permalink to &quot;第二遍：结构与证据&quot;">​</a></h3><p>每一段是否承担清楚功能？主张与证据是否对应？例子是否真的支持结论？限制是否出现在读者做决定之前？</p><h3 id="第三遍-句子与意义" tabindex="-1">第三遍：句子与意义 <a class="header-anchor" href="#第三遍-句子与意义" aria-label="Permalink to &quot;第三遍：句子与意义&quot;">​</a></h3><p>主体、动作、时间、条件、否定、指向和确定性是否清楚？若结构反复改变意思，转入<a href="./../../templates/grammar-evidence">语法证据卡</a>做延迟复测。</p><h3 id="第四遍-语域与声音" tabindex="-1">第四遍：语域与声音 <a class="header-anchor" href="#第四遍-语域与声音" aria-label="Permalink to &quot;第四遍：语域与声音&quot;">​</a></h3><p>这句话是必要纠错、歧义修复、语域选择，还是个人风格？删掉空话和重复，但不要因为“更像母语者”就抹去作者立场。礼貌不是把请求藏起来，专业也不是把句子写长。</p><h3 id="第五遍-交付与边界" tabindex="-1">第五遍：交付与边界 <a class="header-anchor" href="#第五遍-交付与边界" aria-label="Permalink to &quot;第五遍：交付与边界&quot;">​</a></h3><p>检查标题、主题行、格式、链接、引用、附件、隐私、版权、权限、负责人、截止时间和回滚。问：读者离开作者以后能否继续？</p><p>每一遍只记录最影响结果的一到三个变化，保留修改前、修改后和理由。无法解释的修改先不要自动接受。</p><h2 id="_7-让反馈进入下一版-而不是停在批注里" tabindex="-1">7. 让反馈进入下一版，而不是停在批注里 <a class="header-anchor" href="#_7-让反馈进入下一版-而不是停在批注里" aria-label="Permalink to &quot;7. 让反馈进入下一版，而不是停在批注里&quot;">​</a></h2><p>不要只问“写得怎么样”。给反馈者一个任务：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">请先复述你理解的主旨、依据和下一步。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">标出需要猜测、证据不足或语气不合关系的位置。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">区分必要纠错、歧义、语域选择和风格偏好。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">不要直接重写全文；说明最影响任务的三项问题。</span></span></code></pre></div><p>对每条反馈做决定：采纳、部分采纳、拒绝或延后，并写理由。读者可能看见作者盲点，也可能带着不同知识、身份和偏好进入文本。反馈不是命令，拒绝也不能只靠自尊。</p><p>二语写作研究显示，书面纠错与同伴反馈在许多条件下能改善特定表现；效果受到熟练度、体裁、时间、任务和反馈吸收方式影响。修改旧稿比在新任务中独立调用更容易，所以反馈后必须写一个平行文本。</p><h2 id="_8-ai-是编辑助手-不是隐形作者" tabindex="-1">8. AI 是编辑助手，不是隐形作者 <a class="header-anchor" href="#_8-ai-是编辑助手-不是隐形作者" aria-label="Permalink to &quot;8. AI 是编辑助手，不是隐形作者&quot;">​</a></h2><p>AI 适合做：模拟不同读者、定位可能缺失的背景、分类问题、检查候选引用、比较两个版本的意义、生成反例和提出平行任务。</p><p>一个可审计流程：</p><ol><li>先保存自己的任务卡、来源账本和无辅助初稿；</li><li>只请求诊断，不先请求全文重写；</li><li>要求 AI 给出修改依据、置信度和可能误判；</li><li>自己逐项改写并记录采纳/拒绝理由；</li><li>核对事实、引语、链接、隐私和语域；</li><li>关闭 AI，在新主题下完成平行任务；</li><li>按机构、学校、客户或招聘流程要求披露使用范围。</li></ol><p>模型可能把可接受变体写成错误、制造不存在的来源、抹平个人声音，也可能让一份不真实的经历变得极其可信。不要让它虚构项目、客户、职责、数据和结果；不要让它替你完成禁止使用外部帮助的考试、申请或 take-home 任务。</p><p>自动写作评价研究的平均结果可以支持“工具可能帮助反馈”，不能证明任何一段模型润色都提高了作者能力。验收仍是：关掉工具以后，你是否能解释每项修改，并在新任务中完成。</p><h2 id="_9-异步写作要让工作继续" tabindex="-1">9. 异步写作要让工作继续 <a class="header-anchor" href="#_9-异步写作要让工作继续" aria-label="Permalink to &quot;9. 异步写作要让工作继续&quot;">​</a></h2><p>远程协作经常没有即时会议补充。一份可用的状态更新可以按这个顺序：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">一句结论：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">已完成与证据位置：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">当前风险/阻塞：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">需要谁在何时决定什么：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">下一步与负责人：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">若没有回应将怎样处理：</span></span></code></pre></div><p>邮件主题行应帮助分流，例如 <code>[Decision by 15:00 UTC]</code>、<code>[Blocked]</code>、<code>[FYI]</code>，但必须与正文真实紧迫度相符。附件、链接与权限要在发送前验证。</p><p>交接文档至少写明当前状态、已验证事实、未完成项、失败/回滚、环境/版本、责任人和下次检查点。写作在这里不是语言练习，而是降低协作对作者本人在线状态的依赖。</p><h2 id="_10-诚实标题、引用和署名" tabindex="-1">10. 诚实标题、引用和署名 <a class="header-anchor" href="#_10-诚实标题、引用和署名" aria-label="Permalink to &quot;10. 诚实标题、引用和署名&quot;">​</a></h2><p>标题可以有张力，不能承诺正文无法交付的东西。引用要让读者回到原始位置，改写也不能隐去他人贡献。涉及共同写作时，提前说明谁提供材料、谁起草、谁核验、谁批准、谁对最终版本负责。</p><p>署名意味着：我愿意承认这些话来自谁，依据是什么，会影响谁，还有什么不能确定。AI、编辑和同伴可以参与，但最终发布者不能把责任留在工具窗口里。</p><p>我希望自己做一个诚实的作者：允许文章不完美，允许后来修改，但不故意误导读者，也不借流畅掩盖证据空缺。</p><h2 id="_11-十四天写作实验" tabindex="-1">11. 十四天写作实验 <a class="header-anchor" href="#_11-十四天写作实验" aria-label="Permalink to &quot;11. 十四天写作实验&quot;">​</a></h2><table tabindex="0"><thead><tr><th>天数</th><th>动作</th><th>留下的证据</th></tr></thead><tbody><tr><td>1</td><td>选择真实受众与任务，完成限时初稿</td><td>原始文本、条件、意图与未知项</td></tr><tr><td>2</td><td>建立事实与责任账本</td><td>主张、来源、权限和置信度</td></tr><tr><td>3</td><td>标记段落功能与文档骨架</td><td>结构地图与删除项</td></tr><tr><td>4</td><td>比较母语意图、英文首版与翻译</td><td>意义变化和决定理由</td></tr><tr><td>5</td><td>修任务、事实与证据</td><td>第二版和来源核验</td></tr><tr><td>6</td><td>修句子、语域与声音</td><td>修改前后及分类</td></tr><tr><td>7</td><td>交给真实读者复述</td><td>主旨、疑问和下一步</td></tr><tr><td>8</td><td>记录反馈采纳与拒绝</td><td>反馈吸收表</td></tr><tr><td>9</td><td>完成交付与边界检查</td><td>链接、附件、权限和责任人</td></tr><tr><td>10</td><td>换受众重写同一信息</td><td>语域与结构迁移</td></tr><tr><td>11</td><td>换主题写同一体裁</td><td>词汇与内容迁移</td></tr><tr><td>12</td><td>让 AI/同伴提出反例或遗漏</td><td>核验与拒绝理由</td></tr><tr><td>13</td><td>在时间压力下完成异步更新/交接</td><td>真实使用结果</td></tr><tr><td>14</td><td>关闭工具完成平行任务并决定下一轮</td><td>保留、调整或转向依据</td></tr></tbody></table><p>十四天不是写作速成期限。它回答：没有熟悉原稿和即时润色、受众或主题改变后，你是否仍能完成一份愿意署名、能够被使用的文本？</p><h2 id="_12-怎样判断写作正在变成能力" tabindex="-1">12. 怎样判断写作正在变成能力 <a class="header-anchor" href="#_12-怎样判断写作正在变成能力" aria-label="Permalink to &quot;12. 怎样判断写作正在变成能力&quot;">​</a></h2><ul><li>能在限时内留下自己的初稿，而不是只留下工具成品；</li><li>读者能复述目的、依据、限制和下一步；</li><li>能区分事实、来源、推断、个人经验和建议；</li><li>每一段都有工作，删除漂亮句子也不会失去主线；</li><li>能说明翻译或 AI 修改改变了什么意义；</li><li>能区分必要纠错、歧义、语域和风格，并解释决定；</li><li>反馈能进入新文本，而不只让旧稿变漂亮；</li><li>异步读者不依赖额外会议就能继续、决定或回滚；</li><li>换受众、主题和体裁后，仍能完成相近交付；</li><li>愿意为标题、引用、隐私、事实和署名承担责任。</li></ul><p>写作进步有时不是句子越来越华丽，而是读者越来越少猜测。你知道何时给出事实，何时承认未知，何时删掉一句只服务于自我形象的话。文字开始离开作者仍然工作，也开始在时间过去以后留下可以重新核对的自己。</p><h2 id="来源与边界" tabindex="-1">来源与边界 <a class="header-anchor" href="#来源与边界" aria-label="Permalink to &quot;来源与边界&quot;">​</a></h2><ul><li><a href="https://doi.org/10.1111/modl.12189" target="_blank" rel="noreferrer">Kang &amp; Han (2015), The Efficacy of Written Corrective Feedback in Improving L2 Written Accuracy</a>：元分析综合 21 项研究，显示书面纠错可能改善二语写作语法准确性，同时效果受到熟练度、环境和体裁等变量影响。</li><li><a href="https://doi.org/10.1002/tesq.3178" target="_blank" rel="noreferrer">Vuogan &amp; Li (2022), Examining the Effectiveness of Peer Feedback in Second Language Writing</a>：元分析汇总 26 项研究，报告同伴反馈的总体正向效果；来源间比较和部分调节结论受原始研究数量限制。</li><li><a href="https://doi.org/10.1177/07356331221127300" target="_blank" rel="noreferrer">Zhai &amp; Ma (2022), The Effectiveness of Automated Writing Evaluation on Writing Quality</a>：元分析综合 26 项研究与 2468 名参与者，报告自动写作评价的平均效果及教育阶段、语言背景和体裁差异；不等于任何工具输出都可靠。</li><li>写作任务、体裁、受众、机构规则、版权和可接受 AI 使用会变化。重要文本应回到当前事实、一手来源、真实读者和明确责任人验收。</li></ul><p>相关入口：<a href="./grammar">语法篇</a> ｜ <a href="./4-reading">阅读篇</a> ｜ <a href="./5-speaking">口语篇</a> ｜ <a href="./7-ai">用 AI 学英语</a> ｜ <a href="./8-job-search-english">求职英语篇</a> ｜ <a href="./../../templates/writing-evidence">写作证据卡</a> ｜ <a href="./../part-3/4-artifacts-and-delivery">作品篇</a></p><h2 id="结语-写下愿意署名的版本" tabindex="-1">结语：写下愿意署名的版本 <a class="header-anchor" href="#结语-写下愿意署名的版本" aria-label="Permalink to &quot;结语：写下愿意署名的版本&quot;">​</a></h2><p>这个世界已经足够吵闹。写作不必再制造更多噪音，它可以替生活保留一块能够回看的安静地方，也让一个判断在离开当下情绪以后，仍然接受事实、读者和时间的追问。</p><p>初稿记录你当时能够想到什么，修订则记录你是否愿意让新证据和他人的理解改变自己。文字不必一次完美，但每一次准备交付，都应该比上一次更诚实地回答：这是谁的话，依据是什么，会影响谁，还有什么不能确定。</p><p>如果不知道从哪里开始，就写一封真实邮件、一段说明，或一篇 200 字短文。把它交给一个真实的人，听他复述你到底说了什么；然后改到你愿意署名、愿意承担，也愿意在未来重新打开。</p>`,80)])])}const u=i(l,[["render",r]]);export{b as __pageData,u as default};
